architecture.h4_f:
msg = CBOR{v:1, tekst, odgovor_na, poslano_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, tekst, reply_to?, thread_id?, spominje?, poslano_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
žica = CBOR{
  v: 1,
  šifrirani tekst: hex(ct), // promjenjiva dužina
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  poslano_at: unix_ms
}

cryptoWire.h5_f:
vanjski = CBOR{
  izvor_čvor: hex32,
  ciljni_korisnik: int64,
  unutrašnji_ciphertext: bajtovi,
  inner_nonce: bajtovi,
  poslano_at: unix_ms
}
sig = Ed25519-Sign(source_priv, outer)
POST /federation/deliver { omotnica: vanjska, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { korisničko ime, lozinka, x25519_javni_ključ, ime za prikaz, telefon?, email?, avatar_emoji }

Odgovor 201 Kreiran:
  { access_token, refresh_token, user_id, korisničko ime, ... }

auth.h3_f:
access_token korisni teret:
  { sub: user_id, jti: device_id, typ: "access", exp: sada + 15 min }
refresh_token korisni teret:
  { sub: user_id, jti: device_id, typ: "osvježi", exp: sada + 30d }

HS256-potpisano 64-bajtnom tajnom čvora iz .env

auth.h4_f:
register_begin(): izazov = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, izazov }
                    opcije povrata

register_finish(attest):
  provjeriti potvrdu protiv TPM / Sigurne enklave korijena CA
  store { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bitni heksadecimalni, ttl: 60 }
QR nosivost = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → registrovan novi uređaj; JWT su se vratili.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
šifrirani tekst = AES-GCM-Šifriranje (ključ_soba, nonce, CBOR_korisno opterećenje, aad=id_prostora)

Okvir koji se širi: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {upload_id, chunk_size}
komad PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bajtova>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL nedovršeno: 24 h

files.h4_f:
deny_list = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) u deny_list: vrati 415

presence.h1_f:
klijent: pri prvom pritisku na tipku → pošalji {type:"t", state:"start"}
         nema više slanja 3 s osim ako se stanje ne promijeni
         10 s nakon posljednjeg pritiska na tipku → pošalji {type:"t", stanje:"stop"}
prijemnik: auto-stop 10 s nakon posljednjeg "start" ako "stop" nije stigao

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS emitiranje {type:"c", kind:"invite", call_id}
WS emitiranje {type:"c", kind:"offer", sdp}
WS emitiranje {type:"c", kind:"answer", sdp}
WS emitiranje {type:"c", vrsta:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
koverta = {
  izvor_čvor: hex32,
  target_user : int64,
  unutrašnji_ciphertext: bajtovi,
  inner_nonce : bajtovi,
  poslano_at : unix_ms,
}
sig = Ed25519Sign(izvor_priva, CBOR(koverta))
POST /federation/deliver { koverat, sig }

gossip.h3_f:
advertisement = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(reklama))
nosivost trača: [..., {ad, sig}, ...]

prijemnik: potvrdi sig na ad.pubkey → pohrani ako je ok
dodatno: PoW od 2^18 vodećih nula na {pubkey, endpoint}

stealth.h2_f:
ClientHello bajtovi = chrome_120_template sa {
  nasumično = naš slučajni slučaj,
  server_name = naše ime hosta (ili ECH-upakovano),
  session_id = id naše sesije,
}
JA4 = t13d_xxxx_xxxx_xxxx (odgovara trenutnoj Chrome stabilnoj)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domen(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data)}
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
alat = znak_alat
ulaz = izvorno stablo, ključevi/release.key
manifest = {
  verzija: "0.1.0",
  izgrađen_at: unix_ms,
  fajlovi: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
izlaz = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
kreiraj: POST /api/bots {username, display_name, code}
          → {bot_id, token, pubkey}
pokrenuti: u procesu (korutina unutar čvora)
      OR eksterno (duga anketa /api/bots/{id}/ažuriranja, token-auth'd)
poruka: {tekst, potpis: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
na /start {
  emitovati "Dobrodošao, {ctx.first_name}"
}
na /add <item> {
  state.list = (state.list ili []) + [ctx.args.item]
  emit "Dodano: {ctx.args.item}"
}

security.h4_f:
canary.txt (dnevno):
  {datum, sig: Ed25519-Sign(release_priv, date)}
klijent verifikuje → odsutan ili nevažeći ⇒ sumnja na kompromis

hitan slučaj:
  admin POST /api/admin/revoke-all {razlog}
  čvor emitira {type:"n", event:"compromise", reason}
  klijenti brišu ključeve, prisiljavaju ponovno pokretanje

debugging.h2_f:
histogrami stope (po ruti + metodi):
  vortex_http_requests_total{ruta,metod,status}
  vortex_http_request_duration_seconds_bucket{route,method,le}

mjerači websocket:
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{room,user}

prilagođeni brojači:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

